 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    counts={v:sum(row.count(v) for row in grid) for v in set(v for row in grid for v in row)}
    bg=max(counts,key=counts.get)
    # For each diagonal color segment, extrapolate its outward-facing endpoint.
    for color in sorted(counts, key=lambda x: -counts[x]):
        if color==bg or counts[color]<2: continue
        pts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color}
        starts=[]
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1)):
                if (r-dr,c-dc) in pts and (r+dr,c+dc) not in pts:
                    starts.append((r,c,dr,dc))
        for r,c,dr,dc in starts:
            rr,cc=r,c
            while 0<=rr+dr<h and 0<=cc+dc<w:
                rr,cc=rr+dr,cc+dc
                if grid[rr][cc]==bg: out[rr][cc]=color
                else: break
    return out

